def balanced_index(arr):
  prefix_sum = 0
  postfix_sum = sum(arr) - arr[0]

  for i in range(len(arr)):
    if prefix_sum == postfix_sum:
      return i
    prefix_sum += arr[i]
    if i + 1 < len(arr):
      postfix_sum -= arr[i+1]
  return -1

