function balancedIndex(arr) {
  let prefixSum = 0;
  let postfixSum = arr.reduce((a, b) => a + b, 0) - arr[0];

  for (let i = 0; i < arr.length; i++) {
    if (prefixSum === postfixSum) {
      return i;
    }
    prefixSum += arr[i];
    if (i + 1 < arr.length) {
      postfixSum -= arr[i + 1];
    }
  }
  return -1;
}

