class BalancedIndex {
  public int solve(int[] arr) {
    int prefixSum = 0;
    int postfixSum = 0;
    for (int x : arr) {
      postfixSum += x;
    }
    postfixSum -= arr[0];

    for (int i = 0; i < arr.length; i++) {
      if (prefixSum == postfixSum) {
        return i;
      }
      prefixSum += arr[i];
      if (i + 1 < arr.length) {
        postfixSum -= arr[i + 1];
      }
    }
    return -1;
  }
}

